B=/Users/zach/dev/aip-skillbench/build/authoring/drone-planning-control-curated-single-20261008-100410; cd $B/scratch/fresh1; wc -c e2.txt; python3 - <<'EOF'
import json,os,numpy as np
s=json.load(open('o2.json'))['state']
print([k for k in s])
print('all_pass',s['all_pass']); print('tuning',json.dumps(s['tuning_results'])[:800])
for k in s:
    if k not in('results','commands','task_statement','pack_contract','installed_modules','tuning_results','tuning_top_candidates'): print(k, json.dumps(s[k])[:300])
r=s['results']; print(json.dumps(r[0])[:600])
R='results'; mx=(0,None); miss=[]
p=json.load(open(s['params_path'].replace('system_params.yaml','system_params.yaml'))) if False else None
for d in sorted(os.listdir(R)):
    for f in ['planned_trajectory.npy','metrics_3d.json','tuning_results.json','plots/desired_vs_actual.png','plots/errors.png','plots/cumulative_errors.png']:
        if not os.path.exists(f'{R}/{d}/{f}'): miss.append(f'{d}/{f}')
    m=json.load(open(f'{R}/{d}/metrics_3d.json')); t=np.load(f'{R}/{d}/planned_trajectory.npy')
    a=t[12:15]; 
    print(d,m['mode'],t.shape,{k:round(v,4) if isinstance(v,float) else v for k,v in m.items() if k!='mode'}, 'az[min,max]=%.2f,%.2f axy=%.2f'%(a[2].min(),a[2].max(),np.hypot(a[0],a[1]).max()))
    if m['SteadyStateError']>mx[0]: mx=(m['SteadyStateError'],d)
print('dirs',len(os.listdir(R)),'missing',miss,'maxSSE',mx)
print(json.load(open(f'{R}/001/tuning_results.json')).keys())
EOF
